"be quiet — быть тихим, stay in your seat — сидеть на месте, be on time — приходить вовремя, wear a uniform — носить форму.": "be quiet — тыныш болу, stay in your seat — орныңда отыру, be on time — уақытында келу, wear a uniform — форма кию.",
"bed — beds. После s, x, sh, ch и у некоторых слов на o: box — boxes, dish — dishes, watch — watches, potato — potatoes.": "bed — beds. s, x, sh, ch-тен кейін және o-мен біткен кейбір сөздерде: box — boxes, dish — dishes, watch — watches, potato — potatoes.",
