"drawing — рисование, painting — живопись, picture — картина, brush — кисть.": "drawing — сурет салу, painting — кескіндеме, picture — сурет, brush — қылқалам.",
"drum — барабан, tambourine — тамбурин. Это percussion instruments.": "drum — барабан, tambourine — дап. Бұлар percussion instruments.",
