"flute — флейта. Это woodwind instrument.": "flute — сыбызғы (флейта). Бұл woodwind instrument.",
"get up early — вставать рано, have breakfast — завтракать, work all day — работать весь день, have dinner — ужинать.": "get up early — ерте тұру, have breakfast — таңғы ас ішу, work all day — күні бойы жұмыс істеу, have dinner — кешкі ас ішу.",
"get up — вставать, have breakfast — завтракать, go to school — идти в школу.": "get up — тұру, have breakfast — таңғы ас ішу, go to school — мектепке бару.",
"good — хороший, bad — плохой, polite — вежливый, rude — грубый, kind — добрый.": "good — жақсы, bad — жаман, polite — сыпайы, rude — дөрекі, kind — мейірімді.",
"grandmother — бабушка, grandfather — дедушка, aunt — тётя, uncle — дядя, cousin — двоюродный брат или сестра.": "grandmother — әже, grandfather — ата, aunt — тәте, uncle — ағай, cousin — немере аға-іні немесе апа-қарындас.",
"have lunch — обедать, do my homework — делать домашнее задание, watch TV — смотреть телевизор, have dinner — ужинать, go to bed — ложиться спать.": "have lunch — түскі ас ішу, do my homework — үй тапсырмасын орындау, watch TV — теледидар көру, have dinner — кешкі ас ішу, go to bed — ұйықтауға жату.",
"he / she и always / never": "he / she және always / never",
"helmet — каска, van — фургон, shop — магазин, uniform — форма, parcel — посылка, bread — хлеб.": "helmet — каска, van — фургон, shop — дүкен, uniform — форма, parcel — сәлемдеме, bread — нан.",
"helmet — шлем, seat belt — ремень безопасности, pavement — тротуар, zebra crossing — зебра. Always wear a helmet! Never play in the street!": "helmet — дулыға, seat belt — қауіпсіздік белбеуі, pavement — тротуар, zebra crossing — жаяу жүргіншілер өтетін жер (зебра). Always wear a helmet! Never play in the street!",
"help sick people — помогать больным (doctor — врач). teach pupils — учить учеников (teacher — учитель).": "help sick people — науқастарға көмектесу (doctor — дәрігер). teach pupils — оқушыларды оқыту (teacher — мұғалім).",
"in the morning — утром, in the afternoon — днём, in the evening — вечером, at night — ночью.": "in the morning — таңертең, in the afternoon — күндіз, in the evening — кешке, at night — түнде.",
"isn't + глагол с -ing.": "isn't + -ing қосымшалы етістік.",
"make bread — печь хлеб (baker — пекарь). sell vegetables — продавать овощи (shop assistant — продавец).": "make bread — нан пісіру (baker — наубайшы). sell vegetables — көкөніс сату (shop assistant — сатушы).",
"me — меня, you — тебя, him — его, her — её, it — его, us — нас, them — их. Пример: Look at him!": "me — мені, you — сені, him — оны (ұлды), her — оны (қызды), it — оны (затты), us — бізді, them — оларды. Мысал: Look at him!",
"mine и yours": "mine және yours",
"mother — мама, father — папа, parents — родители, brother — брат, sister — сестра.": "mother — шеше (ана), father — әке, parents — ата-ана, brother — аға (іні), sister — апа (қарындас).",
"my — мой, your — твой, his — его, her — её, its — его, её, our — наш, their — их. Пример: This is my helmet.": "my — менің, your — сенің, his — оның, her — оның, its — оның, our — біздің, their — олардың. Мысал: This is my helmet.",
"piano — пианино. Это keyboard instrument.": "piano — пианино. Бұл keyboard instrument.",
"play hopscotch — играть в классики, play chess — играть в шахматы, have a sack race — бежать в мешках, skip — прыгать через скакалку, hide-and-seek — прятки, board game — настольная игра.": "play hopscotch — классик ойнау, play chess — шахмат ойнау, have a sack race — қапқа кіріп жүгіру, skip — секіртпе (арқан) секіру, hide-and-seek — жасырынбақ, board game — үстел ойыны.",
"play — playing, jump — jumping, swim — swimming (m удваивается), climb — climbing.": "play — playing, jump — jumping, swim — swimming (m әрпі екі еселенеді), climb — climbing.",
"police officer — полицейский, firefighter — пожарный, doctor — врач, farmer — фермер, greengrocer — зеленщик, baker — пекарь.": "police officer — полиция қызметкері, firefighter — өрт сөндіруші, doctor — дәрігер, farmer — фермер, greengrocer — көкөніс сатушы, baker — наубайшы.",
"postman, postwoman — почтальон, teacher — учитель, vet — ветеринар, driver — водитель, builder — строитель, nurse — медсестра.": "postman, postwoman — пошташы, teacher — мұғалім, vet — мал дәрігері, driver — жүргізуші, builder — құрылысшы, nurse — медбике.",
"racket — ракетка, net — сетка, bat — бита, ball — мяч, stick — клюшка.": "racket — ракетка, net — тор, bat — таяқ (бита), ball — доп, stick — ойын таяғы.",
"run — running, skip — skipping, jog — jogging. Короткий глагол кончается на одну согласную: буква удваивается.": "run — running, skip — skipping, jog — jogging. Қысқа етістік бір дауыссыз дыбысқа бітеді: әріп екі еселенеді.",
"shout — кричать, make noise — шуметь, drop litter — бросать мусор, chew gum — жевать жвачку.": "shout — айқайлау, make noise — шу шығару, drop litter — қоқыс тастау, chew gum — сағыз шайнау.",
"take out the rubbish — выносить мусор, tidy the room — убирать комнату, walk the dog — выгуливать собаку, water the plants — поливать цветы.": "take out the rubbish — қоқысты шығару, tidy the room — бөлмені жинау, walk the dog — итті серуендету, water the plants — гүлдерді суару.",
"violin — скрипка, guitar — гитара, dombyra — домбра, kobyz — кобыз. Это string instruments.": "violin — скрипка, guitar — гитара, dombyra — домбыра, kobyz — қобыз. Бұлар string instruments.",
"«Always wear a helmet» значит «Никогда не надевай шлем».": "«Always wear a helmet» — «Дулығаны ешқашан тақпа» дегенді білдіреді.",
