"How many meals do we need every day? — Сколько приёмов пищи нужно каждый день? Three meals and one or two snacks. We need a lot of water.": "How many meals do we need every day? — Күн сайын неше рет тамақтану керек? Three meals and one or two snacks. We need a lot of water.",
"I am from + страна.": "I am from + ел.",
"I am from Kazakhstan. I am Kazakh. — Я из Казахстана. Я казах. He is from Great Britain. He is British. — Он из Великобритании. Он британец.": "I am from Kazakhstan. I am Kazakh. — Мен Қазақстаннанмын. Мен қазақпын. He is from Great Britain. He is British. — Ол Ұлыбританиядан. Ол британдық.",
"In front of — перед.": "In front of — алдында.",
"In the forest — в лесу. On the mountain — на горе. At the park — в парке. On Monday — в понедельник. At five o'clock — в пять часов.": "In the forest — орманда. On the mountain — тауда. At the park — паркте. On Monday — дүйсенбіде. At five o'clock — сағат бесте.",
